hooks.command:
python -c "
import json,sys,subprocess,re
d=json.load(sys.stdin)
cmd=d.get('tool_input',{}).get('command','')
def deny(reason):
    print(json.dumps({'hookSpecificOutput':{'hookEventName':'PreToolUse','permissionDecision':'deny','permissionDecisionReason':reason}}))
m=re.search(r'(?:^|[;&|\n])\s*git\s+push\b[^\n;&|]*', cmd)
seg=m.group(0) if m else ''
if not m:
    print('{}')
elif re.search(r'--force(-with-lease)?\b|(?:^|\s)-f\b', seg):
    deny('Force-push is blocked by project policy: ask the user explicitly before force-pushing.')
else:
    branch=subprocess.run(['git','-C','$CLAUDE_PROJECT_DIR','rev-parse','--abbrev-ref','HEAD'],capture_output=True,text=True).stdout.strip()
    if re.search(r'\bmain\b', seg) or branch=='main':
        deny('Direct push to main is blocked: land changes via a PR from My_Work_Befor_PR (see CLAUDE.md PR merge policy).')
    else:
        print('{}')
"
